'use client';

import type { Variants } from 'motion/react';
import { motion, useAnimation } from 'motion/react';
import type { HTMLAttributes } from 'react';
import { forwardRef } from 'react';
import { useIconAnimation } from '@/lib/use-icon-animation';
import { cn } from '@/lib/utils';

export interface CrownIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface CrownIconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

// The crown gives one restrained lift around its fixed center jewel.
const crownBodyVariants: Variants = {
  normal: {
    transform: 'translateY(0px) scale(1)',
    transition: { duration: 0.18, ease: [0.23, 1, 0.32, 1] },
  },
  animate: {
    transform: [
      'translateY(0px) scale(1)',
      'translateY(0.35px) scale(0.992)',
      'translateY(-0.45px) scale(1.018)',
      'translateY(-0.1px) scale(1.006)',
      'translateY(0px) scale(1)',
    ],
    transition: {
      duration: 0.78,
      ease: [0.77, 0, 0.175, 1],
      times: [0, 0.2, 0.52, 0.78, 1],
    },
  },
};

const glintVariants: Variants = {
  normal: {
    opacity: 0,
    visibility: 'hidden',
    transform: 'scale(0.75)',
    transition: { duration: 0.12, ease: [0.23, 1, 0.32, 1] },
  },
  animate: (i: number) => ({
    opacity: [0, 0, 1, 0.7, 0],
    visibility: ['hidden', 'hidden', 'visible', 'visible', 'hidden'],
    transform: [
      'scale(0.75)',
      'scale(0.75)',
      'scale(1)',
      'scale(0.94)',
      'scale(0.8)',
    ],
    transition: {
      duration: 0.82,
      ease: [0.23, 1, 0.32, 1],
      repeat: Infinity,
      repeatDelay: 0.28,
      delay: 0.16 + i * 0.34,
      times: [0, 0.2, 0.42, 0.7, 1],
    },
  }),
};
const generatedGeometryVariants: Variants = {
  normal: { visibility: 'hidden', transition: { duration: 0.08 } },
  animate: { visibility: 'visible', transition: { duration: 0.08 } },
};

const CrownIcon = forwardRef<CrownIconHandle, CrownIconProps>(
  ({ onMouseEnter, onMouseLeave, className, size = 28, ...props }, ref) => {
    const controls = useAnimation();
    const { handleMouseEnter, handleMouseLeave } = useIconAnimation({
      controls,
      loops: true,
      onMouseEnter,
      onMouseLeave,
      ref,
    });

    return (
      <div
        className={cn(className)}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...props}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          overflow="visible"
        >
          <path
            d="M5 21H19"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
          />
